previewCss:
.darma-loader-darma-b16-dial-up-handshake { --accent: var(--loader-color, #16a34a); --accent-2: var(--loader-secondary-color, #f59e0b); width: var(--loader-size, 128px); height: calc(var(--loader-size, 128px) * .42); position: relative; display: flex; gap: 2%; align-items: center; justify-content: space-between; }
.darma-loader-darma-b16-dial-up-handshake span { flex: 1; height: 60%; border-radius: 3px; background: linear-gradient(var(--accent-2), var(--accent)); transform-origin: 50% 50%; animation: darma-loader-darma-b16-dial-up-handshake-modem-screech calc(var(--loader-speed, 1s) * .9) ease-in-out infinite; }
.darma-loader-darma-b16-dial-up-handshake span:nth-of-type(1) { animation-delay: calc(var(--loader-speed, 1s) * -.11); }
.darma-loader-darma-b16-dial-up-handshake span:nth-of-type(2) { animation-delay: calc(var(--loader-speed, 1s) * -.43); }
.darma-loader-darma-b16-dial-up-handshake span:nth-of-type(3) { animation-delay: calc(var(--loader-speed, 1s) * -.07); }
.darma-loader-darma-b16-dial-up-handshake span:nth-of-type(4) { animation-delay: calc(var(--loader-speed, 1s) * -.62); }
.darma-loader-darma-b16-dial-up-handshake span:nth-of-type(5) { animation-delay: calc(var(--loader-speed, 1s) * -.29); }
.darma-loader-darma-b16-dial-up-handshake span:nth-of-type(6) { animation-delay: calc(var(--loader-speed, 1s) * -.78); }
.darma-loader-darma-b16-dial-up-handshake span:nth-of-type(7) { animation-delay: calc(var(--loader-speed, 1s) * -.19); }
.darma-loader-darma-b16-dial-up-handshake span:nth-of-type(8) { animation-delay: calc(var(--loader-speed, 1s) * -.51); }
.darma-loader-darma-b16-dial-up-handshake span:nth-of-type(9) { animation-delay: calc(var(--loader-speed, 1s) * -.35); }
.darma-loader-darma-b16-dial-up-handshake .darma-loader-darma-b16-dial-up-handshake__link { position: absolute; left: 0; right: 0; bottom: 0; height: 8%; border-radius: 3px; background: color-mix(in srgb, var(--accent) 22%, transparent); overflow: hidden; }
.darma-loader-darma-b16-dial-up-handshake .darma-loader-darma-b16-dial-up-handshake__link::after { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 0; background: var(--accent); animation: darma-loader-darma-b16-dial-up-handshake-modem-connect calc(var(--loader-speed, 1s) * 4.5) ease-in-out infinite; }
@keyframes darma-loader-darma-b16-dial-up-handshake-modem-screech { 0%, 100% { transform: scaleY(.28); } 50% { transform: scaleY(1); } }
@keyframes darma-loader-darma-b16-dial-up-handshake-modem-connect { 0% { width: 0; } 30% { width: 22%; } 44% { width: 26%; } 72% { width: 68%; } 92%, 100% { width: 100%; } }

